package org.apache.commons.lang3;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;
import java.util.Locale;
import org.apache.commons.lang3.text.WordUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for StringUtils.containsAny(CharSequence, char[])
 */
public class StringUtils_containsAny_TriageGen2Test {

    @Test
    public void testContainsAny_NullCharSequence() {
        assertFalse(StringUtils.containsAny(null, new char[]{'a'}));
    }

    @Test
    public void testContainsAny_EmptyCharSequence() {
        assertFalse(StringUtils.containsAny("", new char[]{'a'}));
    }

    @Test
    public void testContainsAny_NullSearchChars() {
        assertFalse(StringUtils.containsAny("abc", null));
    }

    @Test
    public void testContainsAny_EmptySearchChars() {
        assertFalse(StringUtils.containsAny("abc", new char[]{}));
    }

    @Test
    public void testContainsAny_NoMatch() {
        assertFalse(StringUtils.containsAny("abcdef", new char[]{'x', 'y', 'z'}));
    }

    @Test
    public void testContainsAny_SingleMatch() {
        assertTrue(StringUtils.containsAny("abcdef", new char[]{'c'}));
    }

    @Test
    public void testContainsAny_MultipleMatches() {
        assertTrue(StringUtils.containsAny("abcdef", new char[]{'a', 'f'}));
    }

    @Test
    public void testContainsAny_MatchAtStart() {
        assertTrue(StringUtils.containsAny("abc", new char[]{'a'}));
    }

    @Test
    public void testContainsAny_MatchAtEnd() {
        assertTrue(StringUtils.containsAny("abc", new char[]{'c'}));
    }

    @Test
    public void testContainsAny_MatchInMiddle() {
        assertTrue(StringUtils.containsAny("abc", new char[]{'b'}));
    }

    @Test
    public void testContainsAny_WithSupplementaryCharacters_LogicPath() {
        // The code contains a branch: if (false && j < searchLastIndex && ...)
        // Since the first condition is 'false', the entire 'if' block is unreachable.
        // This test ensures we cover the 'else' branch which is the only executable path for character matching.

        // Testing a surrogate pair character in the source
        // U+1F600 (Grinning Face) is represented by \uD83D\uDE00
        String emoji = "\uD83D\uDE00";
        char[] search = new char[]{'a', '\uD83D'};

        // Even though it's a high surrogate, the 'false' condition forces the 'else' branch
        assertTrue("Should return true because the high surrogate is found and the branch is forced to else",
                StringUtils.containsAny(emoji, search));
    }

    @Test
    public void testContainsAny_BasicMultilingualPlane() {
        assertTrue(StringUtils.containsAny("Hello World", new char[]{'H', 'W'}));
        assertFalse(StringUtils.containsAny("Hello World", new char[]{'z'}));
    }

    @Test
    public void testContainsAny_LargeSearchArray() {
        char[] largeSearch = new char[1000];
        for (int i = 0; i < 1000; i++) {
            largeSearch[i] = (char) i;
        }
        assertTrue(StringUtils.containsAny("test", new char[]{'t'}));
        assertFalse(StringUtils.containsAny("test", new char[]{'z'}));
    }
}
